def run(context):
  outcomes = context['sql'][0]['result']
  summary = {
    'outcome_summary': [],
    'winner_patterns': [],
    'failure_patterns': [],
    'route_improvements': [],
    'next_checks': []
  }
  for row in outcomes:
    sector = row['sector']
    targets_hit = row['targets_hit']
    stops_hit = row['stops_hit']
    signal_count = row['signal_count']
    summary['outcome_summary'].append({'sector': sector, 'targets_hit': targets_hit, 'stops_hit': stops_hit, 'total_signals': signal_count})
    if targets_hit > stops_hit:
      summary['winner_patterns'].append(sector)
    else:
      summary['failure_patterns'].append(sector)
  return summary

